getAttachmentDownloadName(file) {
  const name = (file && file.name) || ''
  const url = (file && file.url) || ''
  // 1) 原始文件名本身已带扩展名（如 应急预案.docx / uuid.docx）直接复用
  if (/\.[a-z0-9]{1,12}$/i.test(name.trim())) return name.trim()
