    const decoded = decodeURIComponent(fromQuery.split('/').pop())
    if (/\.[a-z0-9]{1,12}$/i.test(decoded)) return decoded
  }
  const seg = url.split('?')[0].split('/').pop()
  if (seg && /\.[a-z0-9]{1,12}$/i.test(seg)) return seg
  // 3) 仍取不到扩展名时，真实的文件名/扩展名由 downloadGet 从响应头 Content-Disposition 补齐
  return name || this.getAttachmentName(url, 0)
},

